import type { Stone } from "./stones";

/**
 * Real lab-grown stock, supplied by the trade desk (Surat). Report numbers are
 * intentionally left out of this file — they ship in the client bundle like
 * everything else here, and the site's design promises those only "on
 * enquiry", not to every visitor.
 *
 * `shape` groups stones by outline for filtering and the 3D wireframe;
 * `shapeName` keeps the supplier's own cut name for display. The two diverge
 * for a few real cuts with no dedicated shape of their own: "Octagonal" (an
 * eight-sided mixed cut) files under "asscher", whose outline is already
 * described as reading like an octagon; "Portuguese Cut" and "Round Mixed
 * Cut" (both round outlines with extra facet rows) file under "round".
 *
 * `cut` is omitted for every stone here except literal round brilliants —
 * IGI issues an overall cut grade only for that shape, leaving it blank on
 * every fancy-shape report in this batch.
 *
 * `color` holds a D–J grade for colourless-scale stones, or the report's own
 * fancy-colour wording ("Fancy Vivid Blue") for stones graded on that scale
 * instead — the two are mutually exclusive, never both graded on one report.
 * `isColorGrade()` in stones.ts tells the two apart wherever code needs to
 * (filtering, sorting) rather than guessing from the string's shape.
 *
 * Stock location (Surat or New York, on this supplier's reports) isn't
 * captured here either, for the same reason as the report number: it isn't
 * shown anywhere on the site, and there's no reason to ship it to every
 * visitor's browser.
 */
